from IPython.display import display, Markdown

md_text = """
# Mobile Account Opening: Problem Framing

Mobile account opening fails for three different reasons, but they are often treated as one generic *“system issue.”*
This leads to weak diagnosis, delayed fixes, and repeated operational leakage.

## Core Question
**Which layer is creating the maximum friction in the account opening journey, and how much business impact does each layer create?**

---

## Hypothesis Framework (MECE)

### 1. Access Failures = Infrastructure Gaps
Access failures are not random user mistakes; they are often explainable by:
- Latency spikes
- Region-specific infrastructure issues
- Device constraints
- Time-window (peak hour) effects

---

### 2. Maker-Checker Breakdowns = Control Failures
Maker-checker breakdowns are process/control failures driven by:
- Field-level validation errors
- Caching issues
- Branch-level operational inconsistencies

---

### 3. CBS Posting Failures = Systemic Failure
CBS posting failures are systemic and propagate from:
- Upstream technical instability
- API failures and retries
- Data loss and reconciliation mismatches

---

### 4. Funnel Impact (Business Lens)
The account-opening funnel can be improved by identifying:
- Which friction point reduces conversion the most
- Which layer increases rework and turnaround time (TAT)
- Where intervention delivers maximum business impact

---
"""

display(Markdown(md_text))

