# -------------------------------------------------
# 1) Clean and standardize datatypes
# -------------------------------------------------
for df_name, df_obj in {"auth_logs": auth_logs, "workflow_logs": workflow_logs, "integration_logs": integration_logs, "transaction_master": transaction_master}.items():
    df_obj.columns = df_obj.columns.str.strip()
    # Parse timestamps
