print("Note: Differences are expected due to feature scaling and model learning process. A direct match is not expected.")


# (d) Build the single canonical production function
# DEPLOYMENT_THRESHOLD is already defined from Section 3 results.

def score_account_opening_risk(features: dict) -> dict:
    """
    Production scoring function for mobile account opening risk.

    Built from LogisticRegression model.coef_ fitted on synthetic training data.
    Threshold tuned on validation set.

    NOTE: This model was developed on synthetic data. Re-train and re-validate
    on real transaction data before production deployment.

    Args:
        features: dict with keys matching the feature set used in training
    Returns:
        dict with keys: risk_score, risk_label, confidence, threshold_used,
                       top_risk_factors
    Raises:
        ValueError: if required keys are missing or values are out of bounds
    """
    import logging

    # Use the globally available DEPLOYMENT_THRESHOLD and best_model_pipeline
    global DEPLOYMENT_THRESHOLD, best_model_pipeline, learned_coefficients

    # Input validation
    # These are the raw features before preprocessing from cell 37417620
    required_keys = [
        "api_latency_ms", "retry_count", "peak_hour_flag", "server_region",
        "hour", "day_of_week", "is_weekend", "latency_band", "retry_band",
        "otp_failure_flag", "session_timeout_flag", "token_mismatch_flag",
        "external_dependency_failure_flag", "client_network_drop_flag",
        "app_crash_flag", "middleware_timeout_flag"
    ]
    missing = [k for k in required_keys if k not in features]
    if missing:
        raise ValueError(f"Missing required features: {missing}")

    # Bounds checking for numerical features
    if 'api_latency_ms' in features:
        # Assuming typical latency range
        if not (0 <= features['api_latency_ms'] <= 10000):
            logging.warning(f"api_latency_ms={{features['api_latency_ms']}} out of expected range [0,10000]. Clipping.")
            features['api_latency_ms'] = max(0, min(10000, features['api_latency_ms']))

    if 'retry_count' in features:
        # Assuming typical retry count range
        if not (0 <= features['retry_count'] <= 5):
            logging.warning(f"retry_count={{features['retry_count']}} out of expected range [0,5]. Clipping.")
            features['retry_count'] = max(0, min(5, features['retry_count']))

    # Convert flags to int if they are bools
    for flag_key in ['peak_hour_flag', 'is_weekend', 'otp_failure_flag', 'session_timeout_flag',
                     'token_mismatch_flag', 'external_dependency_failure_flag',
                     'client_network_drop_flag', 'app_crash_flag', 'middleware_timeout_flag']:
        if flag_key in features and isinstance(features[flag_key], bool):
            features[flag_key] = int(features[flag_key])

    # Score using the fitted pipeline
    input_df = pd.DataFrame([features])
    risk_score = best_model_pipeline.predict_proba(input_df)[0, 1]
    risk_label = int(risk_score >= DEPLOYMENT_THRESHOLD)

    # Top contributing factors (features with highest absolute coefficients for general importance)
    # Or specifically positive coefficients if we want risk-increasing factors
    # Using absolute coefficients to capture overall influence
    top_factors = sorted(
        [(feature.replace('num__', '').replace('cat__', '').replace('_', ' ').title(), abs(coef))
         for feature, coef in learned_coefficients.items()],
        key=lambda x: x[1], reverse=True
    )[:3] # Top 3 by magnitude

    return {
        "risk_score": round(float(risk_score), 4),
        "risk_label": risk_label,
        "confidence": round(float(abs(risk_score - 0.5) * 2), 4), # How far is the score from 0.5
        "threshold_used": DEPLOYMENT_THRESHOLD,
        "top_risk_factors": [f[0] for f in top_factors] # Only feature names
    }

# Demo call with one sample from X_test (raw features before preprocessing)
sample = X_test.iloc[0].to_dict()
