# No duplicate function definitions (check in current global scope)
def find_duplicates(names):
    seen = set()
    duplicates = set()
    for name in names:
        if callable(globals().get(name)):
            if name in seen:
                duplicates.add(name)
            else:
                seen.add(name)
    return list(duplicates)

