# FIX 2: Update get_mece_layer to use the new MECE_LAYER_MAP
def get_mece_layer(feature_name):
    # Remove preprocessor prefixes like 'num__', 'cat__' and one-hot encoding suffixes
    clean_name = re.sub(r'^(num__|cat__)', '', feature_name)

    # Check for direct matches in MECE_LAYER_MAP
    for key, layer in MECE_LAYER_MAP.items():
        if key in clean_name:
            return layer

    # Handle specific cases for one-hot encoded features not directly in MECE_LAYER_MAP keys
    # e.g., 'cat__server_region_East' should map to 'Access'
    if any(k in clean_name for k in ['server_region', 'latency_band', 'retry_band', 'hour', 'day_of_week', 'is_weekend']):
        return 'Access'

    # Handle specific cases for one-hot encoded CBS features
    if any(k in clean_name for k in ['api_call_status', 'cbs_sync_status', 'api_latency_band_integration', 'retry_band_integration']):
        return 'CBS'

    return 'Other'

