import pandas as pd
import numpy as np

# -------------------------------------------------
# 0) Load data
# -------------------------------------------------
auth_logs = pd.read_csv("auth_logs.csv")
workflow_logs = pd.read_csv("workflow_logs.csv")
integration_logs = pd.read_csv("integration_logs.csv")
transaction_master = pd.read_csv("transaction_master.csv")

# -------------------------------------------------
# 1) Clean and standardize datatypes
# -------------------------------------------------
for df in [auth_logs, workflow_logs, integration_logs, transaction_master]:
    df.columns = df.columns.str.strip()

# Parse timestamps
auth_logs["login_timestamp"] = pd.to_datetime(auth_logs["login_timestamp"], errors="coerce")
workflow_logs["submission_timestamp"] = pd.to_datetime(workflow_logs["submission_timestamp"], errors="coerce")
workflow_logs["approval_timestamp"] = pd.to_datetime(workflow_logs["approval_timestamp"], errors="coerce")
integration_logs["timestamp"] = pd.to_datetime(integration_logs["timestamp"], errors="coerce")
transaction_master["txn_date"] = pd.to_datetime(transaction_master["txn_date"], errors="coerce")

# Standardize boolean-like columns
bool_cols = ["field_error_flag", "caching_issue_flag", "reconciliation_flag", "data_loss_flag"]
for col in bool_cols:
    for df in [workflow_logs, integration_logs]:
        if col in df.columns:
            df[col] = df[col].astype(str).str.lower().map({
                "true": 1, "false": 0, "1": 1, "0": 0
            }).fillna(df[col]).astype(int)

# Replace string "None" with actual missing values
for df in [auth_logs, workflow_logs, integration_logs, transaction_master]:
    df.replace(["None", "none", "NULL", "null", ""], np.nan, inplace=True)

# -------------------------------------------------
# 2) Frame the dependent variables first
# -------------------------------------------------
# Access failure: 1 if login failed, else 0
auth_logs["y_access_failure"] = (auth_logs["login_status"].astype(str).str.lower() == "failure").astype(int)

# Maker-checker breakdown: 1 if rework, else 0
workflow_logs["y_maker_checker_breakdown"] = (
    workflow_logs["status"].astype(str).str.lower().isin(["rework", "rejected"])
).astype(int)

# CBS posting failure: 1 if CBS sync failed, else 0
integration_logs["y_cbs_posting_failure"] = (
    integration_logs["cbs_sync_status"].astype(str).str.lower() == "failed"
).astype(int)

# End-to-end account opening failure: 1 if final status failed, else 0
transaction_master["y_account_opening_failure"] = (
    transaction_master["final_status"].astype(str).str.lower() == "failed"
).astype(int)

# -------------------------------------------------
# 3) Convert raw data into analysis-ready features
# -------------------------------------------------
# ---------
# Auth features
# ---------
auth_feat = auth_logs.copy()

auth_feat["hour"] = auth_feat["login_timestamp"].dt.hour
auth_feat["day_of_week"] = auth_feat["login_timestamp"].dt.dayofweek  # Monday=0
auth_feat["is_weekend"] = auth_feat["day_of_week"].isin([5, 6]).astype(int)
auth_feat["peak_hour_flag"] = auth_feat["hour"].isin([9, 10, 11]).astype(int)

auth_feat["latency_band"] = pd.cut(
    auth_feat["api_latency_ms"],
    bins=[-np.inf, 500, 1000, 2000, np.inf],
    labels=["low", "moderate", "high", "very_high"]
)

auth_feat["retry_band"] = pd.cut(
    auth_feat["retry_count"],
    bins=[-np.inf, 0, 1, 2, np.inf],
    labels=["none", "low", "medium", "high"]
)

auth_feat["failure_reason"] = auth_feat["failure_reason"].fillna("No_Failure")

# ---------
# Workflow features
# ---------
workflow_feat = workflow_logs.copy()

workflow_feat["tat_hours"] = workflow_feat["tat_minutes"] / 60.0
workflow_feat["tat_bucket"] = pd.cut(
    workflow_feat["tat_minutes"],
    bins=[-np.inf, 15, 30, 60, 120, np.inf],
    labels=["<=15m", "15-30m", "30-60m", "1-2h", ">2h"]
)

workflow_feat["approval_delay_minutes"] = (
    (workflow_feat["approval_timestamp"] - workflow_feat["submission_timestamp"])
    .dt.total_seconds() / 60.0
)

workflow_feat["submission_hour"] = workflow_feat["submission_timestamp"].dt.hour
workflow_feat["submission_day_of_week"] = workflow_feat["submission_timestamp"].dt.dayofweek
workflow_feat["peak_submission_flag"] = workflow_feat["submission_hour"].isin([9, 10, 11]).astype(int)

workflow_feat["error_field_name"] = workflow_feat["error_field_name"].fillna("No_Error")
workflow_feat["caching_issue_flag"] = workflow_feat["caching_issue_flag"].fillna(0).astype(int)
workflow_feat["field_error_flag"] = workflow_feat["field_error_flag"].fillna(0).astype(int)

# Optional composite risk signal for workflow
workflow_feat["control_risk_score"] = (
    workflow_feat["field_error_flag"] +
    workflow_feat["caching_issue_flag"] +
    (workflow_feat["tat_minutes"] > 60).astype(int)
)

# ---------
# Integration features
# ---------
integration_feat = integration_logs.copy()

integration_feat["event_hour"] = integration_feat["timestamp"].dt.hour
integration_feat["event_day_of_week"] = integration_feat["timestamp"].dt.dayofweek
integration_feat["peak_event_flag"] = integration_feat["event_hour"].isin([9, 10, 11]).astype(int)

integration_feat["api_latency_band"] = pd.cut(
    integration_feat["api_latency_ms"],
    bins=[-np.inf, 500, 1000, 2000, np.inf],
    labels=["low", "moderate", "high", "very_high"]
)

integration_feat["retry_band"] = pd.cut(
    integration_feat["retry_attempts"],
    bins=[-np.inf, 0, 1, 2, np.inf],
    labels=["none", "low", "medium", "high"]
)

integration_feat["sync_risk_score"] = (
    integration_feat["y_cbs_posting_failure"] +
    integration_feat["reconciliation_flag"].astype(int) +
    integration_feat["data_loss_flag"].astype(int) +
    (integration_feat["api_latency_ms"] > 1000).astype(int)
)

# ---------
# Master features
# ---------
master_feat = transaction_master.copy()
master_feat["txn_month"] = master_feat["txn_date"].dt.month
master_feat["txn_day_of_week"] = master_feat["txn_date"].dt.dayofweek

# -------------------------------------------------
# 4) Merge into one analysis table
# -------------------------------------------------
# Merge workflow + auth by transaction timestamp alignment is not direct in sample,
# so we join using maker_id = user_id where appropriate and txn_id for the transaction flow.
#
# Since auth_logs has no txn_id, we align using row-level ordering assumption from generation
# or use timestamp-based merge if  real data has a common key.

# If  matching row order from synthetic generation, create row index keys:
auth_feat = auth_feat.reset_index(drop=True).copy()
workflow_feat = workflow_feat.reset_index(drop=True).copy()
integration_feat = integration_feat.reset_index(drop=True).copy()
master_feat = master_feat.reset_index(drop=True).copy()

auth_feat["row_id"] = np.arange(len(auth_feat))
workflow_feat["row_id"] = np.arange(len(workflow_feat))
integration_feat["row_id"] = np.arange(len(integration_feat))
master_feat["row_id"] = np.arange(len(master_feat))

# Build a single modeling table
model_df = (
    workflow_feat[[
        "row_id", "txn_id", "maker_id", "checker_id", "field_error_flag",
        "error_field_name", "caching_issue_flag", "submission_timestamp",
        "approval_timestamp", "tat_minutes", "tat_hours", "tat_bucket",
        "submission_hour", "submission_day_of_week", "peak_submission_flag",
        "approval_delay_minutes", "control_risk_score",
        "y_maker_checker_breakdown"
    ]]
    .merge(auth_feat[[
        "row_id", "user_id", "device_id", "login_timestamp", "login_status",
        "failure_reason", "api_latency_ms", "server_region", "retry_count",
        "hour", "day_of_week", "is_weekend", "peak_hour_flag",
        "latency_band", "retry_band", "y_access_failure"
    ]], on="row_id", how="left", suffixes=("", "_auth"))
    .merge(integration_feat[[
        "row_id", "api_call_status", "api_latency_ms", "retry_attempts",
        "cbs_sync_status", "reconciliation_flag", "data_loss_flag",
        "timestamp", "event_hour", "event_day_of_week", "peak_event_flag",
        "api_latency_band", "retry_band", "sync_risk_score",
        "y_cbs_posting_failure"
    ]], on="row_id", how="left", suffixes=("", "_int"))
    .merge(master_feat[[
        "row_id", "account_type", "channel", "branch_id", "txn_date",
        "txn_month", "txn_day_of_week", "y_account_opening_failure"
    ]], on="row_id", how="left")
)

# -------------------------------------------------
# 5) Final modeling features
# -------------------------------------------------
# A few high-value engineered variables for analysis
model_df["total_failure_layers"] = (
    model_df["y_access_failure"].fillna(0).astype(int) +
    model_df["y_maker_checker_breakdown"].fillna(0).astype(int) +
    model_df["y_cbs_posting_failure"].fillna(0).astype(int)
)

model_df["end_to_end_friction_score"] = (
    model_df["control_risk_score"].fillna(0) +
    model_df["sync_risk_score"].fillna(0) +
    model_df["peak_hour_flag"].fillna(0) +
    model_df["peak_submission_flag"].fillna(0)
)

model_df["is_slow_auth"] = (model_df["api_latency_ms"] > 1000).astype(int)
model_df["is_slow_cbs"] = (model_df["api_latency_ms_int"] > 1000 if "api_latency_ms_int" in model_df.columns else 0)

# Fix duplicate column issue from merges if needed
# Rename integration latency column for clarity if both auth and integration latency exist
if "api_latency_ms_int" not in model_df.columns and "api_latency_ms" in model_df.columns:
    # If merge suffix did not create distinct columns, create explicit copies before merge in your source data.
    pass

# -------------------------------------------------
# 6) Keep only analysis-ready columns
# -------------------------------------------------
analysis_columns = [
    # Targets
    "y_access_failure",
    "y_maker_checker_breakdown",
    "y_cbs_posting_failure",
    "y_account_opening_failure",

    # Access features
    "peak_hour_flag", "latency_band", "server_region", "retry_count", "is_weekend",

    # Workflow features
    "field_error_flag", "error_field_name", "caching_issue_flag", "tat_minutes",
    "tat_hours", "tat_bucket", "peak_submission_flag", "control_risk_score",

    # CBS features
    "api_call_status", "cbs_sync_status", "reconciliation_flag", "data_loss_flag",
    "retry_attempts", "api_latency_band", "sync_risk_score", "peak_event_flag",

    # Funnel / business features
    "account_type", "channel", "branch_id", "txn_month", "txn_day_of_week",
    "end_to_end_friction_score", "total_failure_layers"
]

analysis_df = model_df[[c for c in analysis_columns if c in model_df.columns]].copy()

# Optional: clean category strings for modeling
for col in analysis_df.select_dtypes(include="object").columns:
    analysis_df[col] = analysis_df[col].astype(str).str.strip()

print("Modeling dataset shape:", analysis_df.shape)
print(analysis_df.head())

import pandas as pd
import numpy as np

# =========================================================
# 1) Load the modeling dataframe
# =========================================================
df = analysis_df.copy()

# Normalize column names
df.columns = df.columns.str.strip()

# Standardize missing values
df.replace(["None", "none", "NULL", "null", ""], np.nan, inplace=True)

# Make sure target columns are numeric 0/1
target_cols = [
    "y_access_failure",
    "y_maker_checker_breakdown",
    "y_cbs_posting_failure",
    "y_account_opening_failure",
]

for col in target_cols:
    df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0).astype(int)

# =========================================================
# 2) Define hypothesis-specific feature sets
#    Keep each model MECE and avoid leakage
# =========================================================
ACCESS_FEATURES = [
    "peak_hour_flag",
    "latency_band",
    "server_region",
    "retry_count",
    "is_weekend"
]

WORKFLOW_FEATURES = [
    "field_error_flag",
    "error_field_name",
    "caching_issue_flag",
    "tat_minutes",
    "tat_hours",
    "tat_bucket",
    "peak_submission_flag",
    "control_risk_score"
]

CBS_FEATURES = [
    "api_call_status",
    "cbs_sync_status",
    "reconciliation_flag",
    "data_loss_flag",
    "retry_attempts",
    "api_latency_band",
    "sync_risk_score",
    "peak_event_flag"
]

E2E_FEATURES = [
    "peak_hour_flag",
    "latency_band",
    "server_region",
    "retry_count",
    "is_weekend",
    "field_error_flag",
    "error_field_name",
    "caching_issue_flag",
    "tat_minutes",
    "tat_bucket",
    "peak_submission_flag",
    "control_risk_score",
    "api_call_status",
    "cbs_sync_status",
    "reconciliation_flag",
    "data_loss_flag",
    "retry_attempts",
    "api_latency_band",
    "sync_risk_score",
    "peak_event_flag",
    "account_type",
    "channel",
    "branch_id",
    "txn_month",
    "txn_day_of_week",
    "end_to_end_friction_score",
    "total_failure_layers"
]

# =========================================================
# 3) Utility: clean a modeling slice
# =========================================================
def build_model_frame(data: pd.DataFrame, target: str, features: list, drop_leakage: bool = True):
    """
    Returns a clean model frame for one hypothesis:
    - keeps only requested features + target
    - drops missing rows
    - removes obvious leakage / duplicate targets if present
    """
    use_cols = [target] + [c for c in features if c in data.columns]
    work = data[use_cols].copy()

    # Drop rows with missing target
    work = work.dropna(subset=[target])

    # Optional: remove rows with all-null predictors
    pred_cols = [c for c in work.columns if c != target]
    work = work.dropna(subset=pred_cols, how="all")

    # Convert categorical columns to string for later encoding
    for col in pred_cols:
        if work[col].dtype == "object":
            work[col] = work[col].astype(str).replace("nan", np.nan)

    # Basic class balance report
    balance = work[target].value_counts(dropna=False).sort_index()
    balance_pct = work[target].value_counts(normalize=True, dropna=False).sort_index()

    print(f"\n=== {target} ===")
    print("Rows:", len(work))
    print("Class counts:\n", balance.to_string())
    print("Class %:\n", (balance_pct * 100).round(2).to_string())

    return work

# =========================================================
# 4) Build four clean hypothesis frames
# =========================================================
access_df = build_model_frame(df, "y_access_failure", ACCESS_FEATURES)
workflow_df = build_model_frame(df, "y_maker_checker_breakdown", WORKFLOW_FEATURES)
cbs_df = build_model_frame(df, "y_cbs_posting_failure", CBS_FEATURES)
e2e_df = build_model_frame(df, "y_account_opening_failure", E2E_FEATURES)

# =========================================================
# 5) Optional: quick feature audit for each frame
# =========================================================
def feature_audit(frame: pd.DataFrame, target: str):
    X = frame.drop(columns=[target])
    summary = pd.DataFrame({
        "dtype": X.dtypes.astype(str),
        "missing_pct": (X.isna().mean() * 100).round(2),
        "unique_values": X.nunique(dropna=True)
    }).sort_values(["missing_pct", "unique_values"], ascending=[False, False])
    return summary

print("\n--- Access Feature Audit ---")
print(feature_audit(access_df, "y_access_failure").to_string())

print("\n--- Workflow Feature Audit ---")
print(feature_audit(workflow_df, "y_maker_checker_breakdown").to_string())

print("\n--- CBS Feature Audit ---")
print(feature_audit(cbs_df, "y_cbs_posting_failure").to_string())

print("\n--- E2E Feature Audit ---")
print(feature_audit(e2e_df, "y_account_opening_failure").to_string())

