"""### Optimize RandomForest with GridSearchCV

To further improve the RandomForest model, we will use `GridSearchCV` to find the optimal hyperparameters for `class_weight` and `n_estimators`. This systematic search helps in identifying a configuration that might yield better performance, especially for an early warning system focused on high recall.
"""

import pandas as pd
import numpy as np
from datetime import datetime, timedelta
import random

np.random.seed(42)

N = 99000

# Generate txn_ids
txn_ids = [f"T{100000+i}" for i in range(N)]

# Common fields
user_ids = [f"U{1000+i}" for i in np.random.randint(1, 5000, N)]
device_ids = [f"D{100+i}" for i in np.random.randint(1, 2000, N)]
branches = [f"B{100+i}" for i in np.random.randint(1, 500, N)]

# Time generation
start_date = datetime(2026, 3, 1)
timestamps = [start_date + timedelta(minutes=int(np.random.randint(0, 1440))) for _ in range(N)]

# -------------------------
# 1. AUTH LOGS
# -------------------------
auth_data = []

for i in range(N):
    hour = timestamps[i].hour

    # Peak hour latency
    if 9 <= hour <= 11:
        latency = np.random.randint(1500, 4000)
    else:
        latency = np.random.randint(200, 1200)

    failure_prob = 0.12
    status = "Failure" if np.random.rand() < failure_prob else "Success"

    if status == "Failure":
        reason = np.random.choice(["Invalid PIN", "API Timeout", "Server Error"], p=[0.4,0.4,0.2])
    else:
        reason = None

    auth_data.append([
        user_ids[i],
        device_ids[i],
        timestamps[i],
        status,
        reason,
        latency,
        np.random.choice(["East","West","North","South"]),
        np.random.randint(1,4)
    ])

auth_logs = pd.DataFrame(auth_data, columns=[
    "user_id","device_id","login_timestamp","login_status",
    "failure_reason","api_latency_ms","server_region","retry_count"
])

# -------------------------
# 2. WORKFLOW LOGS
# -------------------------
workflow_data = []

for i in range(N):
    error_flag = np.random.rand() < 0.22
    caching_issue = error_flag and (np.random.rand() < 0.6)

    submission_time = timestamps[i]
    tat = np.random.randint(5, 180) if not error_flag else np.random.randint(60, 300)
    approval_time = submission_time + timedelta(minutes=tat)

    workflow_data.append([
        txn_ids[i],
        user_ids[i],
        f"U{np.random.randint(5000,9000)}",
        error_flag,
        np.random.choice(["Address","KYC_ID","DOB","PAN"]) if error_flag else None,
        caching_issue,
        submission_time,
        approval_time,
        tat,
        "Rework" if error_flag else "Approved"
    ])

workflow_logs = pd.DataFrame(workflow_data, columns=[
    "txn_id","maker_id","checker_id","field_error_flag",
    "error_field_name","caching_issue_flag","submission_timestamp",
    "approval_timestamp","tat_minutes","status"
])

# -------------------------
# 3. INTEGRATION LOGS
# -------------------------
integration_data = []

for i in range(N):
    api_fail = np.random.rand() < 0.07

    if api_fail:
        api_status = "Failure"
        cbs_status = "Failed"
        recon_flag = True
        data_loss = np.random.rand() < 0.5
        latency = np.random.randint(2000, 5000)
        retries = np.random.randint(1,4)
    else:
        api_status = "Success"
        cbs_status = "Synced"
        recon_flag = False
        data_loss = False
        latency = np.random.randint(300, 1200)
        retries = 0

    integration_data.append([
        txn_ids[i],
        api_status,
        latency,
        retries,
        cbs_status,
        recon_flag,
        data_loss,
        timestamps[i]
    ])

integration_logs = pd.DataFrame(integration_data, columns=[
    "txn_id","api_call_status","api_latency_ms","retry_attempts",
    "cbs_sync_status","reconciliation_flag","data_loss_flag","timestamp"
])

# -------------------------
# 4. MASTER TABLE
# -------------------------
master_data = []

for i in range(N):
    final_status = "Failed" if integration_logs.loc[i,"cbs_sync_status"] == "Failed" else "Completed"

    master_data.append([
        txn_ids[i],
        np.random.choice(["Savings","Current"]),
        np.random.choice(["Mobile","Tablet"]),
        branches[i],
        timestamps[i].date(),
        final_status
    ])

transaction_master = pd.DataFrame(master_data, columns=[
    "txn_id","account_type","channel","branch_id","txn_date","final_status"
])

# -------------------------
# EXPORT CSV FILES
# -------------------------
auth_logs.to_csv("auth_logs.csv", index=False)
workflow_logs.to_csv("workflow_logs.csv", index=False)
integration_logs.to_csv("integration_logs.csv", index=False)
transaction_master.to_csv("transaction_master.csv", index=False)

