param_grid = {
    'model__n_estimators': [200, 400, 600],
    'model__class_weight': ['balanced', 'balanced_subsample']
}

# Initialize RandomForestClassifier with some fixed parameters
rf_base = RandomForestClassifier(
    random_state=42,
    n_jobs=-1,
    min_samples_leaf=10
)

# Create a pipeline for GridSearchCV
rf_pipeline = Pipeline(steps=[
    ("prep", preprocessor),
    ("model", rf_base)
])

# Initialize GridSearchCV
grid_search_rf = GridSearchCV(
    estimator=rf_pipeline,
    param_grid=param_grid,
    scoring='average_precision', # Keep PR AUC as the primary scoring metric
    cv=3, # Using 3-fold cross-validation for speed, could increase for more robust results
    verbose=2,
    n_jobs=-1
)

print("Starting GridSearchCV for RandomForest...")
grid_search_rf.fit(X_train, y_train, model__sample_weight=sample_weight_train) # Use sample_weight for training

print("\nBest parameters found:", grid_search_rf.best_params_)
print("Best PR AUC score from Grid Search (on validation folds):", grid_search_rf.best_score_)

"""### Evaluate the Best RandomForest Model from GridSearchCV

Now, let's evaluate the performance of the RandomForest model that was optimized using `GridSearchCV` on the held-out test set. This will provide a fair comparison with the other models previously evaluated.
"""

# Evaluate the best estimator found by GridSearchCV on the test set
best_rf_model = grid_search_rf.best_estimator_

# Predict probabilities on the validation set for threshold tuning
val_prob_best_rf = best_rf_model.predict_proba(X_val)[:, 1]
best_threshold_rf, best_val_f1_rf = tune_threshold_for_f1(y_val, val_prob_best_rf)

# Predict probabilities on the test set
test_prob_best_rf = best_rf_model.predict_proba(X_test)[:, 1]
test_pred_best_rf = (test_prob_best_rf >= best_threshold_rf).astype(int)

# Collect metrics for the optimized RandomForest model
optimized_rf_results = {
    "model": "RandomForest_Optimized",
    "threshold": best_threshold_rf,
    "val_f1": best_val_f1_rf,
    "test_auc": roc_auc_score(y_test, test_prob_best_rf),
    "test_pr_auc": average_precision_score(y_test, test_prob_best_rf),
    "test_accuracy": accuracy_score(y_test, test_pred_best_rf),
    "test_balanced_accuracy": balanced_accuracy_score(y_test, test_pred_best_rf),
    "test_precision": precision_score(y_test, test_pred_best_rf, zero_division=0),
    "test_recall": recall_score(y_test, test_pred_best_rf, zero_division=0),
    "test_f1": f1_score(y_test, test_pred_best_rf, zero_division=0),
    "confusion_matrix": confusion_matrix(y_test, test_pred_best_rf),
    "pipeline": best_rf_model
}

# Add the optimized RF results to the existing results list and re-display
results.append(optimized_rf_results)

results_df_updated = pd.DataFrame([{
    "model": r["model"],
    "threshold": round(r["threshold"], 4),
    "val_f1": round(r["val_f1"], 4),
    "test_auc": round(r["test_auc"], 4),
    "test_pr_auc": round(r["test_pr_auc"], 4),
    "test_accuracy": round(r["test_accuracy"], 4),
    "test_balanced_accuracy": round(r["test_balanced_accuracy"], 4),
    "test_precision": round(r["test_precision"], 4),
    "test_recall": round(r["test_recall"], 4),
    "test_f1": round(r["test_f1"], 4),
} for r in results])

print("\n=== Updated Model Comparison (with Optimized RandomForest) ===")
print(results_df_updated.sort_values("test_pr_auc", ascending=False).to_string(index=False))

print("\nClassification report for Optimized RandomForest on test set:")
print(classification_report(
    y_test,
    (optimized_rf_results['pipeline'].predict_proba(X_test)[:, 1] >= optimized_rf_results['threshold']).astype(int),
    digits=4,
    zero_division=0
))

"""### Context & Direction

Initial modeling showed no predictive signal (AUC ~0.5), indicating that surface-level features like latency band, retries, and peak hour were insufficient to explain access failures. This pointed to a structural issue—missing causal variables. After introducing hidden system-level failure indicators (authentication, middleware, session, client-side), the model achieved strong performance (AUC ~0.82), confirming that failures are driven by underlying system breakdowns rather than observable symptoms.

We now move from validation to optimization—improving recall, incorporating cost-sensitive decisions, segmenting behavior across channels/branches, and designing a real-time early warning system for proactive failure mitigation.
"""

import pandas as pd
import numpy as np

# Target
target = 'y_access_failure_v2'

# Features (ONLY modeling features)
features = [
    'api_latency_ms',
    'retry_count',
    'peak_hour_flag',
    'server_region',
    'hour_band',
    'middleware_timeout_flag',
    'session_timeout_flag',
    'otp_failure_flag',
    'token_mismatch_flag',
    'external_dependency_failure_flag',
    'client_network_drop_flag',
    'app_crash_flag'
]

# Use the `auth` DataFrame (from the previous cell's output, `SUqdnUUZqhod`)
# as it contains `y_access_failure_v2` and the hidden features.
# Also load transaction_master to get 'channel' and 'branch_id'
# and merge based on original row order, as they were generated synthetically.

# Ensure `auth` is the global variable from the previous cell's execution
# If running this cell independently, `auth` needs to be re-created from SUqdnUUZqhod
# For this fix, assuming `auth` from previous cell is in kernel state.

# Create a working copy of the `auth` DataFrame which has the new target and hidden features.
# Adding a row_id for merging purposes.
auth_augmented_df = auth.copy()
auth_augmented_df['row_id'] = np.arange(len(auth_augmented_df))

# Load transaction_master and add a row_id
# Assuming `transaction_master` from the initial data generation is available
transaction_master_df = transaction_master.copy()
transaction_master_df['row_id'] = np.arange(len(transaction_master_df))

# Merge the augmented auth data with transaction_master to get channel and branch_id
df = pd.merge(
    auth_augmented_df[features + [target, 'row_id', 'login_timestamp']],
    transaction_master_df[['row_id', 'channel', 'branch_id']],
    on='row_id',
    how='left'
)

# Drop the temporary row_id column
df = df.drop(columns=['row_id', 'login_timestamp'])

df = df.dropna()

# Normalize column names (already done for auth in the previous cell)
df.columns = df.columns.str.strip()

print(df.columns)

def calculate_real_time_risk(latency, retries, system_flags):
    """
    Calculates a risk score [0-1] for an incoming session.

    Args:
        latency (int): api_latency_ms
        retries (int): retry_count
        system_flags (dict): dictionary containing boolean flags for:
                             middleware_timeout, session_timeout, otp_failure,
                             token_mismatch, external_dependency, client_network, app_crash
    """
    # Coefficients derived from the modeling phase (Hypothesis 1 RE-TEST)
    base_logit = -3.2

    # Feature weights
    weights = {
        'middleware_timeout': 1.05,
        'session_timeout': 0.80,
        'app_crash': 0.95,
        'external_dependency': 0.70,
        'token_mismatch': 0.65,
        'otp_failure': 0.55,
        'client_network': 0.60,
        'latency_factor': 0.0008,
        'retry_factor': 0.15
    }

    # Calculate logit
    logit = base_logit + (latency * weights['latency_factor'])
    if retries >= 2: logit += weights['retry_factor']

    for flag, value in system_flags.items():
        if flag in weights and value == 1:
            logit += weights[flag]

    # Sigmoid to get probability
    risk_score = 1 / (1 + np.exp(-logit))
    return risk_score

# --- Demo of the Early Warning System ---
sample_session = {
    'latency': 2500,
    'retries': 2,
    'system_flags': {
        'middleware_timeout': 1,
        'otp_failure': 0
    }
}

score = calculate_real_time_risk(sample_session['latency'], sample_session['retry_count' if 'retry_count' in sample_session else 'retries'], sample_session['system_flags'])
print(f"Current Risk Score: {score:.4f}")
if score > 0.6158: # Using the optimal threshold from our model
    print("ALERT: High Risk of Access Failure! Triggering Proactive Mitigation.")

import pandas as pd
import numpy as np
from sklearn.metrics import classification_report, confusion_matrix

# Define the system flag columns based on the dataset
flag_cols = [
    'middleware_timeout_flag', 'session_timeout_flag', 'otp_failure_flag',
    'token_mismatch_flag', 'external_dependency_failure_flag',
    'client_network_drop_flag', 'app_crash_flag'
]

def apply_backtest(row):
    # Prepare the system_flags dictionary for the function
    flags = {col.replace('_flag', ''): row[col] for col in flag_cols}
    return calculate_real_time_risk(
        latency=row['api_latency_ms'],
        retries=row['retry_count'],
        system_flags=flags
    )

# 1. Apply the function to the existing dataset
print("Calculating risk scores for backtest...")
df['predicted_risk_score'] = df.apply(apply_backtest, axis=1)

# 2. Apply the decision threshold (0.6158)
threshold = 0.6158
df['predicted_label'] = (df['predicted_risk_score'] >= threshold).astype(int)

# 3. Evaluate Results
print("\n--- Backtest Results ---")
print(f"Target Variable: y_access_failure_v2")
print(f"Threshold Used: {threshold}")

print("\nClassification Report:")
print(classification_report(df['y_access_failure_v2'], df['predicted_label']))

print("\nConfusion Matrix:")
cm = confusion_matrix(df['y_access_failure_v2'], df['predicted_label'])
