# 1. Get Precision, Recall, and Thresholds
precision, recall, thresholds_pr = precision_recall_curve(df['y_access_failure_v2'], df['predicted_risk_score'])

# 2. Plot the trade-off
plt.figure(figsize=(8, 5))
plt.plot(thresholds_pr, precision[:-1], label='Precision', color='blue')
plt.plot(thresholds_pr, recall[:-1], label='Recall', color='green')
