"""### Production Deployment Script

This cell contains the finalized scoring logic and parameters. It is designed to be self-contained for use in a production environment (e.g., a Lambda function or a streaming microservice).
"""

import numpy as np

def predict_access_risk(api_latency_ms, retry_count, system_flags):
    """
    Finalized Risk Scoring Function for Mobile Access Failures.

    Parameters:
    - api_latency_ms (int): Current API latency in milliseconds.
    - retry_count (int): Number of retries attempted in the current session.
    - system_flags (dict): Boolean flags (0 or 1) for specific failure modes:
        ['middleware_timeout', 'session_timeout', 'app_crash',
         'external_dependency', 'token_mismatch', 'otp_failure', 'client_network']

    Returns:
    - dict: Contains 'risk_score' (0-1) and 'is_high_risk' (boolean).
    """
    # 1. Model Parameters (Logit Coefficients)
    BASE_LOGIT = -3.2
    WEIGHTS = {
        'middleware_timeout': 1.05,
        'session_timeout': 0.80,
        'app_crash': 0.95,
        'external_dependency': 0.70,
        'token_mismatch': 0.65,
        'otp_failure': 0.55,
        'client_network': 0.60,
        'latency_factor': 0.0008,
        'retry_factor': 0.15
    }

    # 2. Optimized Decision Threshold (Targeting ~85% Recall)
    OPTIMIZED_THRESHOLD = 0.0874

    # 3. Calculate Logit
    logit = BASE_LOGIT + (api_latency_ms * WEIGHTS['latency_factor'])
    if retry_count >= 2:
        logit += WEIGHTS['retry_factor']

    for flag, is_active in system_flags.items():
        if flag in WEIGHTS and is_active == 1:
            logit += WEIGHTS[flag]

    # 4. Transform to Probability (Risk Score)
    risk_score = 1 / (1 + np.exp(-logit))

    return {
        'risk_score': float(round(risk_score, 4)),
        'is_high_risk': bool(risk_score >= OPTIMIZED_THRESHOLD),
        'threshold_applied': OPTIMIZED_THRESHOLD
    }

# --- Example Production Usage ---
sample_input = {
    'api_latency_ms': 1200,
    'retry_count': 1,
    'system_flags': {
        'middleware_timeout': 0,
        'session_timeout': 1
    }
}

production_result = predict_access_risk(**sample_input)
print(f"Production Score: {production_result}")

