import pandas as pd

def calculate_for(cm):
    # cm is [[TN, FP], [FN, TP]]
    tn, fp, fn, tp = cm.ravel()
    for_score = fn / (fn + tn)
    return for_score

# Calculate FOR for both confusion matrices calculated previously
for_balanced = calculate_for(cm1)
for_proactive = calculate_for(cm2)

for_results = pd.DataFrame({
    'Strategy': ['Balanced (0.6158)', 'Proactive (0.0874)'],
    'False Omission Rate (FOR)': [for_balanced, for_proactive],
    'Meaning': [
        'Risk of missed failure in predicted successes',
        'Risk of missed failure in predicted successes'
    ]
})

display(for_results)

print(f"\nKey Comparison:")
print(f"Under the Proactive strategy, the FOR is {for_proactive:.2%}, meaning only a tiny fraction of 'Safe' labels are actually failures.")
print(f"The Balanced strategy has a higher FOR of {for_balanced:.2%}, representing a higher risk of silent system failures.")

import numpy as np
import matplotlib.pyplot as plt

# Define relative costs
# A False Negative (missed failure) is much more expensive than a False Positive (false alarm)
COST_FN = 15  # Cost of a missed system failure
COST_FP = 1   # Cost of investigating a false alarm

# Calculate costs across a range of thresholds
thresholds = np.linspace(0.01, 0.99, 100)
total_costs = []

y_true = df['y_access_failure_v2']
y_prob = df['predicted_risk_score']

for t in thresholds:
    preds = (y_prob >= t).astype(int)
    fn = ((y_true == 1) & (preds == 0)).sum()
    fp = ((y_true == 0) & (preds == 1)).sum()
    total_cost = (fn * COST_FN) + (fp * COST_FP)
    total_costs.append(total_cost)

# Visualization
plt.figure(figsize=(10, 6))
plt.plot(thresholds, total_costs, color='purple', lw=3, label='Total Operational Cost')

# Mark our two strategy thresholds
plt.axvline(x=0.6158, color='blue', linestyle='--', label='Balanced Strategy (0.6158)')
plt.axvline(x=0.0874, color='red', linestyle='--', label='Proactive Strategy (0.0874)')

# Highlight the 'Sweet Spot'
min_cost_idx = np.argmin(total_costs)
plt.scatter(thresholds[min_cost_idx], total_costs[min_cost_idx], color='black', s=100, zorder=5, label='Theoretical Minimum Cost')

plt.title(f'Cost-Benefit Analysis: Minimizing System Risk\n(Assumes Missed Failure is {COST_FN}x costlier than False Alarm)')
plt.xlabel('Risk Score Threshold')
plt.ylabel('Total Estimated Cost (Units)')
plt.legend()
plt.grid(alpha=0.3)
plt.show()

print(f"Economic Insight: The Proactive threshold (0.0874) sits much closer to the theoretical minimum cost point")
print(f"than the Balanced threshold when the cost of missing a system failure is high.")

