from sklearn.utils import resample
from sklearn.metrics import roc_auc_score, precision_score, recall_score, f1_score

def bootstrap_confidence_interval(model, X_test, y_test, metric_func, n_bootstraps=1000, alpha=0.05):
    """
    Calculates bootstrap confidence intervals for a given metric.

    Args:
        model: Trained scikit-learn pipeline or model with `predict_proba` method.
        X_test (pd.DataFrame): Test features.
        y_test (pd.Series): True labels for the test set.
        metric_func (callable): Metric function (e.g., roc_auc_score, recall_score, precision_score, f1_score).
                                For precision/recall/f1, it should accept y_true, y_pred.
                                For ROC AUC, it should accept y_true, y_prob.
        n_bootstraps (int): Number of bootstrap samples.
        alpha (float): Significance level for the confidence interval (e.g., 0.05 for 95% CI).

    Returns:
        tuple: (lower_bound, upper_bound) of the confidence interval.
    """
    np.random.seed(42) # For reproducibility of bootstrap samples
    scores = []
    n_samples = len(X_test)

    # Determine if the metric needs probabilities or predicted classes
    needs_proba = (metric_func == roc_auc_score)

    # Get original predictions/probabilities for reuse
    if needs_proba:
        original_preds = model.predict_proba(X_test)[:, 1]
    else:
        # For metrics like recall, precision, f1, we need to apply the DEPLOYMENT_THRESHOLD
        # Assuming DEPLOYMENT_THRESHOLD is available from Section 4 or defined globally.
        # Re-using the threshold from the best model in Section 3
        optimal_threshold = None
        for res in results:
            if res['model'] == 'LogisticRegression': # Or whichever model is 'best_model_pipeline'
                optimal_threshold = res['threshold']
                break
        if optimal_threshold is None:
             # Fallback if specific threshold not found (e.g., if results was cleared)
            print("Warning: Optimal threshold not found for classification metrics. Defaulting to 0.5.")
            optimal_threshold = 0.5
        original_preds = (model.predict_proba(X_test)[:, 1] >= optimal_threshold).astype(int)

    for _ in range(n_bootstraps):
        # Resample indices with replacement
        indices = resample(np.arange(n_samples), n_samples=n_samples, random_state=np.random.randint(0, 10000))

        y_true_bootstrap = y_test.iloc[indices]
        y_preds_bootstrap = original_preds[indices]

        # Ensure at least one positive and one negative class in bootstrap sample for metrics to work
        if len(np.unique(y_true_bootstrap)) < 2 or (needs_proba and len(np.unique(y_preds_bootstrap)) < 2): # Check for proba output uniqueness
            continue

        try:
            if needs_proba:
                score = metric_func(y_true_bootstrap, y_preds_bootstrap)
            else:
                # For classification metrics, check if unique predictions are sufficient
                if len(np.unique(y_preds_bootstrap)) < 2:
                     # If only one class predicted, metric might fail, assign 0.0 or skip
                     score = 0.0 # Or np.nan, then filter out later
                else:
                    score = metric_func(y_true_bootstrap, y_preds_bootstrap, zero_division=0)
            scores.append(score)
        except ValueError: # Catch cases where a bootstrap sample might be problematic
            continue

    scores = np.array(scores)
    scores = scores[~np.isnan(scores)] # Remove any NaN scores if they occurred

    if len(scores) == 0:
        return (np.nan, np.nan)

    lower_bound = np.percentile(scores, (alpha / 2) * 100)
    upper_bound = np.percentile(scores, (1 - alpha / 2) * 100)
    return (lower_bound, upper_bound)

# Assuming X_test, y_test, and best_model_pipeline are available from previous cells.
# Use the 'best_model_pipeline' (Logistic Regression from Section 3)
# Extract best_model_pipeline and DEPLOYMENT_THRESHOLD from `results_df` or `results` list
best_model_pipeline = None
deployment_threshold = None

for res in results:
    if res['model'] == 'LogisticRegression': # Assuming 'model' key exists
        best_model_pipeline = res['pipeline']
        deployment_threshold = res['threshold']
        break

if best_model_pipeline is None or deployment_threshold is None:
    raise ValueError("Best model pipeline or deployment threshold not found. Ensure previous cells are run.")

print("Calculating Bootstrap Confidence Intervals (95% CI)...")

# Convert y_test to Series with original index for consistent iloc indexing in bootstrap function
y_test_series = pd.Series(y_test.values, index=X_test.index)

# For metrics requiring `y_pred`, we'll pass the model and threshold will be handled inside `bootstrap_confidence_interval`
# Or, we can directly pass y_pred if we apply threshold once:
preds_on_test = (best_model_pipeline.predict_proba(X_test)[:, 1] >= deployment_threshold).astype(int)

ci_recall = bootstrap_confidence_interval(best_model_pipeline, X_test, y_test_series, recall_score)
ci_precision = bootstrap_confidence_interval(best_model_pipeline, X_test, y_test_series, precision_score)
ci_f1 = bootstrap_confidence_interval(best_model_pipeline, X_test, y_test_series, f1_score)
ci_roc_auc = bootstrap_confidence_interval(best_model_pipeline, X_test, y_test_series, roc_auc_score)

print("\n--- 95% Bootstrap Confidence Intervals (Test Set) ---")
print(f"Recall         : ({ci_recall[0]:.4f}, {ci_recall[1]:.4f})")
print(f"Precision      : ({ci_precision[0]:.4f}, {ci_precision[1]:.4f})")
print(f"F1-Score       : ({ci_f1[0]:.4f}, {ci_f1[1]:.4f})")
print(f"ROC AUC        : ({ci_roc_auc[0]:.4f}, {ci_roc_auc[1]:.4f})")

