"""## 10. Calibration Analysis

Model calibration assesses how well the predicted probabilities align with the true likelihood of the event. A well-calibrated model means that if it predicts a probability of 0.8, the event should occur approximately 80% of the time. This is critical for early warning systems where the numerical risk score directly informs action.
"""

from sklearn.calibration import calibration_curve, CalibratedClassifierCV
from sklearn.metrics import brier_score_loss
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np

# Assuming best_model_pipeline, X_test, y_test, and y_prob_test are available from the setup cell.

