plt.figure(figsize=(10, 6))
plt.plot(mean_predicted_value, fraction_of_positives, "s-", label="Logistic Regression")
plt.plot([0, 1], [0, 1], "k:", label="Perfectly calibrated")
plt.xlabel("Mean predicted probability")
plt.ylabel("Fraction of positives")
plt.title("Reliability Diagram (Calibration Curve)")
plt.legend(loc="lower right")
plt.grid(True)
plt.show()

# 3. Calculate Brier Score
brier_score = brier_score_loss(y_test, y_prob_test)
print(f"Brier Score: {brier_score:.4f}")

# 4. Probability Histogram
plt.figure(figsize=(10, 6))
sns.histplot(y_prob_test, bins=50, kde=True, color='skyblue')
plt.title("Distribution of Predicted Probabilities")
plt.xlabel("Predicted Probability (Risk Score)")
plt.ylabel("Frequency")
plt.grid(True)
plt.show()

print("\n--- Interpretation of Calibration Analysis ---")
print("The **Reliability Diagram** shows how well the predicted probabilities align with the true outcomes. Ideally, the plotted curve should follow the diagonal 'Perfectly calibrated' line. Deviations above the line indicate underprediction (model is too conservative), while deviations below indicate overprediction (model is overconfident).")
print("The **Brier Score** quantifies calibration. A lower Brier Score indicates better calibration (0 is perfectly calibrated).")
print("The **Probability Histogram** visualizes the distribution of predicted risk scores. For imbalanced datasets, it's common to see a high density of predictions near 0 (for the majority class) and 1 (for the minority class, if the model can separate well), or a skewed distribution if the model struggles to assign high probabilities to the rare event.")

