"""## 11. Threshold Optimization for Business Outcomes

Selecting the optimal probability threshold is crucial for translating model scores into actionable decisions. This section generates a comprehensive table of various classification metrics across a range of thresholds, including business-specific costs, to recommend the best deployment threshold based on our risk tolerance and strategic goals.
"""

import pandas as pd
import numpy as np
from sklearn.metrics import confusion_matrix, precision_recall_curve, precision_score, recall_score, f1_score

# Assuming y_test and y_prob_test are available from previous cells.

# Metric utility functions (if not defined globally, define here for self-containment)
def calculate_specificity(y_true, y_pred):
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0,1]).ravel()
    return tn / (tn + fp) if (tn + fp) > 0 else 0.0

def calculate_fpr(y_true, y_pred):
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0,1]).ravel()
    return fp / (fp + tn) if (fp + tn) > 0 else 0.0

def calculate_for(y_true, y_pred):
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0,1]).ravel()
    return fn / (fn + tn) if (fn + tn) > 0 else 1.0 # 1.0 if no negatives predicted

# Cost parameters (can be adjusted based on business input)
COST_FN_MISSED_FAILURE = 15 # Cost of a missed system failure
COST_FP_FALSE_ALARM = 1    # Cost of investigating a false alarm

def generate_threshold_metrics(y_true, y_prob, num_thresholds=100):
    """
    Generates a DataFrame of various metrics across a range of thresholds.
    """
    precision, recall, thresholds_pr = precision_recall_curve(y_true, y_prob)

    # Use a denser range of thresholds for more granular analysis
    thresholds = np.linspace(0, 1, num_thresholds)
    thresholds = np.sort(np.unique(np.concatenate([thresholds_pr, thresholds])))

    metrics_data = []
    for t in thresholds:
        y_pred = (y_prob >= t).astype(int)

        # Handle cases where confusion matrix might be degenerate (all one class predicted)
        if len(np.unique(y_pred)) < 2: # All predictions are the same class
            # If all predicted as 0 (safe)
            if np.all(y_pred == 0):
                tn = np.sum(y_true == 0)
                fp = 0
                fn = np.sum(y_true == 1)
                tp = 0
            # If all predicted as 1 (risk)
            else:
                tn = 0
                fp = np.sum(y_true == 0)
                fn = 0
                tp = np.sum(y_true == 1)
        else:
            tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0, 1]).ravel()

        current_precision = precision_score(y_true, y_pred, zero_division=0)
        current_recall = recall_score(y_true, y_pred, zero_division=0)
        current_f1 = f1_score(y_true, y_pred, zero_division=0)

        current_specificity = calculate_specificity(y_true, y_pred)
        current_for = calculate_for(y_true, y_pred)
        current_fpr = calculate_fpr(y_true, y_pred)
        current_flag_rate = (tp + fp) / len(y_true)
        current_cost = (fn * COST_FN_MISSED_FAILURE) + (fp * COST_FP_FALSE_ALARM)

        metrics_data.append({
            'Threshold': t,
            'Recall': current_recall,
            'Precision': current_precision,
            'Specificity': current_specificity,
            'FOR': current_for,
            'FPR': current_fpr,
            'F1-Score': current_f1,
            'Flag Rate': current_flag_rate,
            'Business Cost': current_cost
        })
    return pd.DataFrame(metrics_data)

# Generate the threshold analysis DataFrame
threshold_df = generate_threshold_metrics(y_test, y_prob_test, num_thresholds=200)

print("--- Threshold Optimization Analysis (Test Set) ---")
display(threshold_df.round(4).head(10))
display(threshold_df.round(4).tail(10))

# --- Automatic Recommendation of Deployment Threshold ---
# Example rule: Find the highest threshold that ensures Recall >= 0.85 and FOR <= 0.075
target_recall = 0.85
max_for = 0.075

qualified_thresholds = threshold_df[
    (threshold_df['Recall'] >= target_recall) &
    (threshold_df['FOR'] <= max_for)
]

recommended_threshold_info = None
if not qualified_thresholds.empty:
    # Prioritize minimizing business cost among qualified thresholds
    # If multiple thresholds have the same min cost, pick the highest threshold (least alerts)
    min_cost = qualified_thresholds['Business Cost'].min()
    best_options = qualified_thresholds[qualified_thresholds['Business Cost'] == min_cost]
    recommended_threshold_info = best_options.sort_values(by='Threshold', ascending=False).iloc[0]
else:
    # Fallback: if no threshold meets both, recommend the one that minimizes business cost overall
    print("Warning: No threshold met both Recall and FOR criteria. Recommending threshold that minimizes overall business cost.")
    recommended_threshold_info = threshold_df.sort_values(by='Business Cost', ascending=True).iloc[0]

print("\n--- Recommended Deployment Threshold ---")
if recommended_threshold_info is not None:
    print(f"Deployment Threshold: {recommended_threshold_info['Threshold']:.4f}")
    print(f"  Rationale: Achieves Recall >= {target_recall*100:.0f}% and FOR <= {max_for*100:.0f}% (or minimizes cost otherwise)")
    print(f"  Metrics at this Threshold:")
    print(f"    Recall       : {recommended_threshold_info['Recall']:.4f}")
    print(f"    Precision    : {recommended_threshold_info['Precision']:.4f}")
    print(f"    Specificity  : {recommended_threshold_info['Specificity']:.4f}")
    print(f"    FOR          : {recommended_threshold_info['FOR']:.4f}")
    print(f"    FPR          : {recommended_threshold_info['FPR']:.4f}")
    print(f"    F1-Score     : {recommended_threshold_info['F1-Score']:.4f}")
    print(f"    Flag Rate    : {recommended_threshold_info['Flag Rate']:.4f}")
    print(f"    Business Cost: {recommended_threshold_info['Business Cost']:.0f}")
else:
    print("Could not recommend a deployment threshold based on the criteria.")

# Store the recommended threshold for final production function
DEPLOYMENT_THRESHOLD_OPTIMIZED = recommended_threshold_info['Threshold']
# %store DEPLOYMENT_THRESHOLD_OPTIMIZED

import pandas as pd
import numpy as np
from sklearn.metrics import confusion_matrix, precision_recall_curve

# Assuming y_test and y_prob_test (from calibration analysis) are available

# Define the metric utility functions (to be moved to a dedicated utility section later)
def calculate_specificity(y_true, y_pred):
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return tn / (tn + fp) if (tn + fp) > 0 else 0.0

def calculate_fpr(y_true, y_pred):
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return fp / (fp + tn) if (fp + tn) > 0 else 0.0

def calculate_for(y_true, y_pred):
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return fn / (fn + tn) if (fn + tn) > 0 else 1.0 # 1.0 if no negatives predicted

def calculate_npv(y_true, y_pred):
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return tn / (tn + fn) if (tn + fn) > 0 else 0.0

# Cost parameters (can be adjusted based on business input)
COST_FN_MISSED_FAILURE = 15 # Cost of a missed system failure
COST_FP_FALSE_ALARM = 1    # Cost of investigating a false alarm

def generate_threshold_metrics(y_true, y_prob, num_thresholds=100):
    """
    Generates a DataFrame of various metrics across a range of thresholds.
    """
    # Use precision_recall_curve to get meaningful thresholds
    precision, recall, thresholds = precision_recall_curve(y_true, y_prob)

    # Only consider thresholds that produce predictions (thresholds has one less element)
    thresholds = np.concatenate(([0.0], thresholds, [1.0])) # Add 0 and 1 for full range

    # Ensure unique and sorted thresholds for stability
    thresholds = np.unique(thresholds)
    thresholds = np.sort(thresholds)

    # If too many thresholds from PR curve, thin them out or use linspace
    if len(thresholds) > num_thresholds:
        thresholds = np.linspace(0, 1, num_thresholds)

    metrics_data = []
    for t in thresholds:
        y_pred = (y_prob >= t).astype(int)
        if len(np.unique(y_pred)) < 2: # Handle cases where only one class is predicted
            # If all predicted as 0 (safe), and there are actual 1s, Recall, F1, Precision will be 0
            # If all predicted as 1 (risk), and there are actual 0s, Specificity, NPV will be 0
            tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0, 1]).ravel()
            if t > 0.5: # Likely predicting all 0
                current_precision = 0.0
                current_recall = 0.0
                current_f1 = 0.0
            else: # Likely predicting all 1
                 current_precision = precision_score(y_true, y_pred, zero_division=0)
                 current_recall = recall_score(y_true, y_pred, zero_division=0)
                 current_f1 = f1_score(y_true, y_pred, zero_division=0)
        else:
            tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0, 1]).ravel()
            current_precision = precision_score(y_true, y_pred, zero_division=0)
            current_recall = recall_score(y_true, y_pred, zero_division=0)
            current_f1 = f1_score(y_true, y_pred, zero_division=0)

        current_specificity = calculate_specificity(y_true, y_pred)
        current_for = calculate_for(y_true, y_pred)
        current_fpr = calculate_fpr(y_true, y_pred)
        current_flag_rate = (tp + fp) / len(y_true)
        current_cost = (fn * COST_FN_MISSED_FAILURE) + (fp * COST_FP_FALSE_ALARM)

        metrics_data.append({
            'Threshold': t,
            'Recall': current_recall,
            'Precision': current_precision,
            'Specificity': current_specificity,
            'FOR': current_for,
            'FPR': current_fpr,
            'F1-Score': current_f1,
            'Flag Rate': current_flag_rate,
            'Business Cost': current_cost
        })
    return pd.DataFrame(metrics_data)

# Generate the threshold analysis DataFrame
threshold_df = generate_threshold_metrics(y_test, y_prob_test, num_thresholds=200)

print("--- Threshold Optimization Analysis (Test Set) ---")
