"""## 12. Confusion Matrix Dashboard

A comprehensive view of the model's performance on the test set, presented as a confusion matrix dashboard. This dashboard displays raw counts, percentages, and a business-centric interpretation of True Positives, False Positives, False Negatives, and True Negatives at the recommended deployment threshold.
"""

import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import confusion_matrix
import pandas as pd

# Assuming y_test, y_prob_test, and DEPLOYMENT_THRESHOLD_OPTIMIZED are available

# Get predictions at the optimized threshold
y_pred_optimized = (y_prob_test >= DEPLOYMENT_THRESHOLD_OPTIMIZED).astype(int)

# Calculate the confusion matrix
cm = confusion_matrix(y_test, y_pred_optimized)
tn, fp, fn, tp = cm.ravel()

total_samples = len(y_test)

# Create a DataFrame for counts
cm_df_counts = pd.DataFrame(cm, index=['Actual 0 (Success)', 'Actual 1 (Failure)'], columns=['Predicted 0 (Safe)', 'Predicted 1 (Risk)']).astype(int)

# Create a DataFrame for percentages
