"""## 13. Metric Utility Functions

This section consolidates reusable Python functions for common classification metrics. These functions promote code consistency, reduce redundancy, and simplify future evaluations and reporting.
"""

from sklearn.metrics import (
    recall_score, precision_score, f1_score, roc_auc_score,
    average_precision_score, balanced_accuracy_score, confusion_matrix
)
import numpy as np

def calculate_recall(y_true, y_pred):
    """Calculates Recall (True Positive Rate)."""
    return recall_score(y_true, y_pred, zero_division=0)

def calculate_precision(y_true, y_pred):
    """Calculates Precision (Positive Predictive Value)."""
    return precision_score(y_true, y_pred, zero_division=0)

def calculate_npv(y_true, y_pred):
    """Calculates Negative Predictive Value."""
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return tn / (tn + fn) if (tn + fn) > 0 else 0.0

def calculate_for(y_true, y_pred):
    """Calculates False Omission Rate."""
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return fn / (fn + tn) if (fn + tn) > 0 else 1.0

def calculate_f1_score(y_true, y_pred):
    """Calculates F1-Score."""
    return f1_score(y_true, y_pred, zero_division=0)

def calculate_roc_auc(y_true, y_prob):
    """Calculates ROC AUC Score."""
    return roc_auc_score(y_true, y_prob)

def calculate_pr_auc(y_true, y_prob):
    """Calculates Precision-Recall AUC (Average Precision Score)."""
    return average_precision_score(y_true, y_prob)

def calculate_balanced_accuracy(y_true, y_pred):
    """Calculates Balanced Accuracy Score."""
    return balanced_accuracy_score(y_true, y_pred)

def calculate_specificity(y_true, y_pred):
    """Calculates Specificity (True Negative Rate)."""
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return tn / (tn + fp) if (tn + fp) > 0 else 0.0

def calculate_fpr(y_true, y_pred):
    """Calculates False Positive Rate."""
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred).ravel()
    return fp / (fp + tn) if (fp + tn) > 0 else 0.0

print("Metric utility functions defined.")

