for i in range(N_TRANSACTIONS):
    hour = transaction_timestamps[i].hour
    region = np.random.choice(["East", "West", "North", "South"])

    if 9 <= hour <= 11:
        latency = np.random.randint(1500, 4000)
    else:
        latency = np.random.randint(200, 1200)

    retry_count = np.random.choice([1, 2, 3], p=[0.7, 0.2, 0.1])

    p_otp_fail = sigmoid(
        -2.6
        + 0.0007 * latency
        + 0.35 * (1 if 9 <= hour <= 11 else 0)
        + 0.15 * (1 if "morning" in str(pd.cut([hour], bins=[-1, 5, 11, 17, 23], labels=["night", "morning", "afternoon", "evening"])[0]) else 0)
    )
    otp_failure_flag = np.random.binomial(1, np.clip(p_otp_fail, 0, 0.95))

    p_session_timeout = sigmoid(
        -3.0
        + 0.0010 * latency
        + 0.25 * (1 if retry_count >= 2 else 0)
        + 0.30 * (1 if 9 <= hour <= 11 else 0)
    )
    session_timeout_flag = np.random.binomial(1, np.clip(p_session_timeout, 0, 0.95))

    p_token_mismatch = sigmoid(
        -3.2
        + 0.0006 * latency
        + 0.20 * (1 if region == "East" else 0)
        + 0.15 * (1 if region == "South" else 0)
    )
    token_mismatch_flag = np.random.binomial(1, np.clip(p_token_mismatch, 0, 0.95))

    p_external_dependency = sigmoid(
        -3.4
        + 0.0008 * latency
        + 0.25 * (1 if region == "East" else 0)
        + 0.20 * (1 if 9 <= hour <= 11 else 0)
    )
    external_dependency_failure_flag = np.random.binomial(1, np.clip(p_external_dependency, 0, 0.95))

    p_client_network_drop = sigmoid(
        -3.1
        + 0.18 * (1 if "evening" in str(pd.cut([hour], bins=[-1, 5, 11, 17, 23], labels=["night", "morning", "afternoon", "evening"])[0]) else 0)
        + 0.12 * (1 if "night" in str(pd.cut([hour], bins=[-1, 5, 11, 17, 23], labels=["night", "morning", "afternoon", "evening"])[0]) else 0)
        + 0.18 * (1 if region == "West" else 0)
    )
    client_network_drop_flag = np.random.binomial(1, np.clip(p_client_network_drop, 0, 0.95))

    p_app_crash = sigmoid(
        -3.6
        + 0.0012 * latency
        + 0.20 * (1 if retry_count >= 3 else 0)
    )
    app_crash_flag = np.random.binomial(1, np.clip(p_app_crash, 0, 0.95))

    p_middleware_timeout = sigmoid(
        -3.3
        + 0.0013 * latency
        + 0.28 * (1 if 9 <= hour <= 11 else 0)
        + 0.18 * (1 if retry_count >= 2 else 0)
    )
    middleware_timeout_flag = np.random.binomial(1, np.clip(p_middleware_timeout, 0, 0.95))

    logit_access_failure = (
        SIM_BASE_LOGIT_ACCESS
        + SIM_OTP_FAIL_WEIGHT * otp_failure_flag
        + SIM_SESSION_TIMEOUT_WEIGHT * session_timeout_flag
        + SIM_TOKEN_MISMATCH_WEIGHT * token_mismatch_flag
        + SIM_EXTERNAL_DEPENDENCY_WEIGHT * external_dependency_failure_flag
        + SIM_CLIENT_NETWORK_DROP_WEIGHT * client_network_drop_flag
        + SIM_APP_CRASH_WEIGHT * app_crash_flag
        + SIM_MIDDLEWARE_TIMEOUT_WEIGHT * middleware_timeout_flag
        + SIM_LATENCY_FACTOR * latency
        + SIM_PEAK_HOUR_FACTOR * (1 if 9 <= hour <= 11 else 0)
        + SIM_RETRY_FACTOR * (1 if retry_count >= 2 else 0)
    )
    prob_access_failure = sigmoid(logit_access_failure)
    access_failure = np.random.binomial(1, np.clip(prob_access_failure, 0, 0.98))
